#!/data/data/com.termux/files/usr/bin/bash
# Giao diện bổ sung cho Nro_Project. Các thao tác được chuyển cho launcher gốc.
root=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd) || exit 1
backend="$root/nro_termux.sh"
mode=${1:-live}
case $mode in live|--demo|--preview) ;; *) echo "bash nro-ui.sh [--demo|--preview]"; exit 2;; esac
if [[ $mode == live && ! -f $backend ]]; then
  echo 'Đặt nro-ui.sh cạnh nro_termux.sh hoặc thêm --demo để xem mẫu.'
  exit 1
fi
if [[ $mode != --preview && ! -t 0 ]]; then echo 'Cần mở terminal tương tác.'; exit 2; fi
amber=$'\e[38;5;221m'; blue=$'\e[38;5;110m'; pale=$'\e[38;5;253m'
mint=$'\e[38;5;115m'; red=$'\e[38;5;209m'; bold=$'\e[1m'; reset=$'\e[0m'
dim=$'\e[38;5;145m'
rule() { printf ' %s' "$blue"; local bar; printf -v bar '%*s' "$((width-2))" ''; printf '%s' "${bar// /─}"; printf '%s\n' "$reset"; }
section() {
  local tail; printf -v tail '%*s' "$((width-${#1}-6))" ''
  printf '\n %s%s▌ %s%s %s%s%s\n' "$amber" "$bold" "$1" "$reset" "$blue" "${tail// /─}" "$reset"
}
tile=$'\e[38;5;230m\e[48;5;24m'
pair() {
  if ((width>=31)); then
    local gap=$((13-${#2})); ((gap<1)) && gap=1
    printf ' %s %s %s %s%*s%s %s %s %s\n' "$tile" "$1" "$reset" "$2" "$gap" '' "$tile" "$3" "$reset" "$4"
  else
    printf ' %s %s %s %s\n' "$tile" "$1" "$reset" "$2" "$tile" "$3" "$reset" "$4"
  fi
}
