refresh_state() {
  if [[ $mode == live ]]; then
    pid=$(pgrep -f 'java.*20[.]jar' 2>/dev/null | head -1)
    rss='—'
    if [[ -n $pid ]]; then
      state='Java đang chạy';statecolor=$mint
      rss=$(ps -o rss= -p "$pid" 2>/dev/null | awk '$1+0>0{print int($1/1024) " MB"}')
      rss=${rss:-—}
    else state='Máy chủ đang tắt';statecolor=$red; fi
    if ! command -v mysqladmin >/dev/null; then database='Chưa có công cụ'
    elif mysqladmin --connect-timeout=1 ping >/dev/null 2>&1; then database='Đang chạy'
    else database='Chưa kết nối'; fi
    note='TERMUX'
  else
    state='Java đang chạy';statecolor=$mint;rss='326 MB';database='Đang chạy';note='BẢN MẪU'
  fi
}
header() {
  local i idx light=""; local -a titles
  for ((i=0;i<7;i++)); do
    if ((i==(frame/2)%7)); then light+="$amber◆"; else light+="$blue·"; fi
  done
  titles=("" "$blue$note$reset" "$bold${amber}NGỌC RỒNG$reset" "${pale}Quản lý máy chủ$reset" "$light$reset" "")
  if ((width<34 || height<24)); then
    printf ' %s◆ NGỌC RỒNG%s · %s\n' "$amber" "$reset" "$note"
    printf ' %s%s\n' "$light" "$reset"
    return
  fi
  for ((i=0;i<6;i++)); do
    idx=$((frame*6+i))
    printf ' %s %s\n' "${orb_rows[idx]}" "${titles[i]}"
  done
}
dimensions() {
  width=$(tput cols 2>/dev/null) || width=${COLUMNS:-40}
  height=$(tput lines 2>/dev/null) || height=${LINES:-30}
  ((width>56)) && width=56
  ((width<12)) && width=12
}
dashboard() {
  header
  rule
  printf ' %s● %s%s\n' "$statecolor" "$state" "$reset"
  printf ' %sRAM Java%s  %s\n %sMariaDB %s  %s\n' "$dim" "$reset" "$rss" "$dim" "$reset" "$database"
  if ((height<23 || width<31)); then
    printf ' %s1%s Bật   %s2%s Tắt   %s3%s Restart\n' "$blue" "$reset" "$blue" "$reset" "$blue" "$reset"
    printf ' 4 Log     5 Cập nhật\n 6 Sao lưu 7 Khôi phục\n 8 RAM     9 Mật khẩu\n G GitHub  I IP / Panel\n O Menu gốc\n A Hiệu ứng  R Tải lại  0 Ra'
    return
  fi
  section 'MÁY CHỦ' 
  pair 1 'Bật server' 2 'Tắt server'
  pair 3 'Khởi động lại' 4 'Nhật ký'
  section 'DỮ LIỆU'
  pair 5 'Cập nhật' 6 'Sao lưu'
  pair 7 'Khôi phục' G 'GitHub'
  section 'CẤU HÌNH'
  pair 8 'Chỉnh RAM' 9 'Mật khẩu'
  pair I 'IP / Panel' O 'Menu gốc'
  rule
  printf ' %s[A]%s Hiệu ứng  %s[R]%s Tải lại  %s[0]%s Ra' "$blue" "$reset" "$blue" "$reset" "$amber" "$reset"
}
frame=0; motion=1
if [[ $mode == --preview ]]; then
  [[ ${2:-} =~ ^[0-9]$|^1[0-5]$ ]] && frame=$2
  dimensions; refresh_state; dashboard; exit
fi
leave() { printf '\e[?25h\e[?1049l'; }
enter() { printf '\e[?1049h\e[?25l'; }
trap leave EXIT
trap 'exit 130' INT
trap 'exit 143' TERM HUP
trap 'dirty=1' WINCH
enter; dirty=1; next_poll=0
while :; do
  if ((SECONDS>=next_poll)); then refresh_state; next_poll=$((SECONDS+15)); dirty=1; fi
  if ((dirty)); then
    dimensions; printf '\e[H\e[2J'; dashboard; dirty=0
  elif ((motion && height>=15)); then
    printf '\e[H'; header
  fi
  delay=1; ((motion)) && delay=0.18
  read -rsn1 -t "$delay" choice
  rc=$?
  if ((rc>128)); then ((motion)) && frame=$(((frame+1)%16)); continue; fi
  ((rc)) && break
  case ${choice^^} in
    A) motion=$((1-motion)); continue;;
    R) next_poll=0;continue;;
    0|Q) break;; 1) action=start;; 2) action=stop;; 3) action=restart;;
    4) action=log;; 5) action=update;; 6) action=backup;; 7) action=restore;;
    8) action=ram;; 9) action=pass;; G) action=github;; I) action=ip;; O) action='';; *) continue;;
  esac
  leave
  if [[ $mode == --demo ]]; then
    printf '\n Bản mẫu · thao tác: %s\n' "${action:-menu gốc}"
  else
    if [[ $action == log ]]; then
      trap ':' INT
      bash "$backend" log
      trap 'exit 130' INT
    elif [[ -n $action ]]; then bash "$backend" "$action"
    else bash "$backend"; fi
  fi
  printf '\n Bấm phím bất kỳ để về menu.'
  read -rsn1 || break
  enter; dirty=1; next_poll=0
done
printf '%s\n' "$reset"
